def pipe(data, *funcs):
    """ Pipe a value through a sequence of functions

    I.e. ``pipe(data, f, g, h)`` is equivalent to ``h(g(f(data)))``

    We think of the value as progressing through a pipe of several
    transformations, much like pipes in UNIX

    ``$ cat data | f | g | h``

    >>> double = lambda i: 2 * i
    >>> pipe(3, double, str)
    '6'

    See Also:
        compose
        thread_first
        thread_last
    """
    for func in funcs:
        data = func(data)
    return data


def compose_left(*funcs):
    """ Compose functions to operate in series, from left to right.

    Returns a function that applies other functions in sequence.

    Functions are applied from left to right so that
    ``compose_left(f, g, h)(x, y)`` is the same as ``h(g(f(x, y)))``.

    This is the opposite order of ``compose``, which applies functions
    from right to left.

    If no arguments are provided, the identity function (f(x) = x) is returned.

    >>> inc = lambda i: i + 1
    >>> double = lambda i: i * 2
    >>> compose_left(str, inc)(3)
    '4'
    >>> compose_left(double, inc)(5)
    11

    See Also:
        compose
        pipe
    """
    if not funcs:
        return identity
    if len(funcs) == 1:
        return funcs[0]
    else:
        return ComposeLeft(funcs)


class ComposeLeft(object):
    """ A composition of functions, applied left to right

    See Also:
        compose_left
    """
    __slots__ = 'first', 'funcs'

    def __init__(self, funcs):
        # Store funcs in order - first is applied first
        self.first = funcs[0]
        self.funcs = funcs[1:]

    def __call__(self, *args, **kwargs):
        ret = self.first(*args, **kwargs)
        for f in self.funcs:
            ret = f(ret)
        return ret

    def __getstate__(self):
        return self.first, self.funcs

    def __setstate__(self, state):
        self.first, self.funcs = state

    @instanceproperty(classval=__doc__)
    def __doc__(self):
        def composed_doc(*fs):
            """Generate a docstring for the composition of fs."""
            if not fs:
                return '*args, **kwargs'
            return '{f}({g})'.format(f=fs[-1].__name__, g=composed_doc(*fs[:-1]))

        try:
            return (
                'lambda *args, **kwargs: ' +
                composed_doc((self.first,) + self.funcs)
            )
        except AttributeError:
            return 'A composition of functions'

    @property
    def __name__(self):
        try:
            return '_of_'.join(
                (f.__name__ for f in (self.first,) + self.funcs)
            )
        except AttributeError:
            return type(self).__name__


